@layer base, ifp, components, utilities;
@layer ifp {
  :root {
    --color-paper: #fffdf5;
    --color-ink: #2b2b33;
    --color-hero: #2d317a;
    --color-emphasis: #6866ad;
    --color-emphasis-fill: #6a64ab;
    --color-band: #06011e;
    --color-meta: #999;
    --color-panel: #faf9f7;
    --color-category-1: #2d317a;
    --color-category-2: #6967ac;
    --color-category-3: #9a96ca;
    --color-category-4: #3f50a0;
    --color-on-category: var(--color-paper);
    --color-accent: var(--color-band);
    --color-hero-background: var(--color-hero);
  }
  .home-splash,
  .hero-intro {
    --color-hero-background: var(--color-hero);
  }
  [data-post-category="metascience"],
  .spotlight-category[href*="/metascience"] {
    --color-category: var(--color-category-1) !important;
    --color-on-category: var(--color-paper);
  }
  [data-post-category="high-skilled-immigration"],
  .spotlight-category[href*="/high-skilled-immigration"] {
    --color-category: var(--color-category-2) !important;
    --color-on-category: var(--color-paper);
  }
  [data-post-category="biotechnology"],
  .spotlight-category[href*="/biotechnology"] {
    --color-category: var(--color-category-3) !important;
    --color-on-category: var(--color-band);
  }
  [data-post-category="infrastructure"],
  .spotlight-category[href*="/infrastructure"] {
    --color-category: var(--color-category-4) !important;
    --color-on-category: var(--color-paper);
  }
  [data-post-category="emerging-technology"],
  .spotlight-category[href*="/emerging-technology"] {
    --color-category: var(--color-category-1) !important;
    --color-on-category: var(--color-paper);
  }
  .spotlight-category[href*="/biotechnology"] .spotlight-category__title,
  .spotlight-category[href*="/biotechnology"] .spotlight-category__icon {
    color: var(--color-band);
  }
  .spotlight-category[href*="/biotechnology"] .spotlight-category__icon svg * {
    fill: var(--color-band);
  }
  :root {
    --easeInSine: cubic-bezier(0.47, 0, 0.745, 0.715);
    --ease-in-sine: cubic-bezier(0.47, 0, 0.745, 0.715);
    --easeOutSine: cubic-bezier(0.39, 0.575, 0.565, 1);
    --ease-out-sine: cubic-bezier(0.39, 0.575, 0.565, 1);
    --easeInOutSine: cubic-bezier(0.445, 0.05, 0.55, 0.95);
    --ease-in-out-sine: cubic-bezier(0.445, 0.05, 0.55, 0.95);
    --easeInQuad: cubic-bezier(0.55, 0.085, 0.68, 0.53);
    --ease-in-quad: cubic-bezier(0.55, 0.085, 0.68, 0.53);
    --easeOutQuad: cubic-bezier(0.25, 0.46, 0.45, 0.94);
    --ease-out-quad: cubic-bezier(0.25, 0.46, 0.45, 0.94);
    --easeInOutQuad: cubic-bezier(0.455, 0.03, 0.515, 0.955);
    --ease-in-out-quad: cubic-bezier(0.455, 0.03, 0.515, 0.955);
    --easeInCubic: cubic-bezier(0.55, 0.055, 0.675, 0.19);
    --ease-in-cubic: cubic-bezier(0.55, 0.055, 0.675, 0.19);
    --easeOutCubic: cubic-bezier(0.215, 0.61, 0.355, 1);
    --ease-out-cubic: cubic-bezier(0.215, 0.61, 0.355, 1);
    --easeInOutCubic: cubic-bezier(0.645, 0.045, 0.355, 1);
    --ease-in-out-cubic: cubic-bezier(0.645, 0.045, 0.355, 1);
    --easeInQuart: cubic-bezier(0.895, 0.03, 0.685, 0.22);
    --ease-in-quart: cubic-bezier(0.895, 0.03, 0.685, 0.22);
    --easeOutQuart: cubic-bezier(0.165, 0.84, 0.44, 1);
    --ease-out-quart: cubic-bezier(0.165, 0.84, 0.44, 1);
    --easeInOutQuart: cubic-bezier(0.77, 0, 0.175, 1);
    --ease-in-out-quart: cubic-bezier(0.77, 0, 0.175, 1);
    --easeInQuint: cubic-bezier(0.755, 0.05, 0.855, 0.06);
    --ease-in-quint: cubic-bezier(0.755, 0.05, 0.855, 0.06);
    --easeOutQuint: cubic-bezier(0.23, 1, 0.32, 1);
    --ease-out-quint: cubic-bezier(0.23, 1, 0.32, 1);
    --easeInOutQuint: cubic-bezier(0.86, 0, 0.07, 1);
    --ease-in-out-quint: cubic-bezier(0.86, 0, 0.07, 1);
    --easeInExpo: cubic-bezier(0.95, 0.05, 0.795, 0.035);
    --ease-in-expo: cubic-bezier(0.95, 0.05, 0.795, 0.035);
    --easeOutExpo: cubic-bezier(0.19, 1, 0.22, 1);
    --ease-out-expo: cubic-bezier(0.19, 1, 0.22, 1);
    --easeInOutExpo: cubic-bezier(1, 0, 0, 1);
    --ease-in-out-expo: cubic-bezier(1, 0, 0, 1);
    --easeInCirc: cubic-bezier(0.6, 0.04, 0.98, 0.335);
    --ease-in-circ: cubic-bezier(0.6, 0.04, 0.98, 0.335);
    --easeOutCirc: cubic-bezier(0.075, 0.82, 0.165, 1);
    --ease-out-circ: cubic-bezier(0.075, 0.82, 0.165, 1);
    --easeInOutCirc: cubic-bezier(0.785, 0.135, 0.15, 0.86);
    --ease-in-out-circ: cubic-bezier(0.785, 0.135, 0.15, 0.86);
    --easeInBack: cubic-bezier(0.6, -0.28, 0.735, 0.045);
    --ease-in-back: cubic-bezier(0.6, -0.28, 0.735, 0.045);
    --easeOutBack: cubic-bezier(0.175, 0.885, 0.32, 1.275);
    --ease-out-back: cubic-bezier(0.175, 0.885, 0.32, 1.275);
    --easeInOutBack: cubic-bezier(0.68, -0.55, 0.265, 1.55);
    --ease-in-out-back: cubic-bezier(0.68, -0.55, 0.265, 1.55);
  }
  ::-moz-selection {
    background: color-mix(in srgb, var(--color-emphasis) 35%, transparent);
  }
  ::selection {
    background: color-mix(in srgb, var(--color-emphasis) 35%, transparent);
  }
  pre {
    white-space: pre;
  }
  .ReactModal__Overlay {
    z-index: 999;
  }

  input,
  button,
  .button {
    border: none;
    border-bottom: 1px solid;
  }
  input:not([type="submit"]) {
    width: 100%;
    padding-bottom: 5px;
  }
  input:not([type="submit"])::-webkit-input-placeholder {
    color: #9a9a90;
  }
  input:not([type="submit"]):-ms-input-placeholder {
    color: #9a9a90;
  }
  input:not([type="submit"])::placeholder {
    color: #9a9a90;
  }
  input[type="submit"],
  button,
  .button {
    text-transform: none;
    font-weight: 900;
    padding-right: 0;
    padding-left: 0;
    text-decoration: none;
  }
  .button {
    padding-bottom: 0.3em;
  }
  .rwmb-select {
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    padding: 5px 10px;
    background-image: url('data:image/svg+xml;utf8,<svg width="11" height="9" viewBox="0 0 11 9" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5.5 8.5L0.736861 0.249999L10.2631 0.25L5.5 8.5Z" fill="%232B2B33"/></svg>');
    background-position: top 50% left 10px;
    background-repeat: no-repeat;
    color: #9a9a90;
  }
  .rwmb-select:valid {
    color: inherit;
  }
  .rwmb-required {
    color: var(--color-emphasis);
    margin-right: 0.2em;
  }
  @media print {
    .site-header,
    .article__toc,
    .article__content .article-reference,
    .article__references,
    .wp-block-separator,
    .newsletter-pre-footer,
    .site-footer {
      display: none !important;
      grid-area: none !important;
    }
    .site-main {
      margin: 0 !important;
    }
    .single-article__header {
      padding-top: 30px;
    }
  }
  @media print and (max-width: 61.24em) {
    .single-article__content {
      margin-left: 12px;
    }
  }
  @media print and (min-width: 61.25em) and (max-width: 63.99em) {
    .single-article__content {
      margin-left: 18px;
    }
  }
  @media print and (min-width: 64em) {
    .single-article__content {
      margin-left: 30px;
    }
  }
  @media print and (max-width: 61.24em) {
    .single-article__content {
      padding-left: 12px;
    }
  }
  @media print and (min-width: 61.25em) and (max-width: 63.99em) {
    .single-article__content {
      padding-left: 18px;
    }
  }
  @media print and (min-width: 64em) {
    .single-article__content {
      padding-left: 30px;
    }
  }
  @media print {
    .single-article__content .article {
      grid-template-columns: 1fr;
    }
  }
  @media print {
    .ifp-collapsible-heading {
      padding-right: 0;
    }
    .collapsible-section__toggle {
      display: none !important;
    }
    .collapsible-section__body--collapsed {
      max-height: none !important;
      overflow: visible;
    }
    .collapsible-section__body--collapsed:after {
      display: none;
    }
  }
  body.nav-open .site-header {
    background: var(--color-band) !important;
    color: var(--color-paper) !important;
    --logo-color: var(--color-paper) !important;
    border-color: var(--color-band);
  }
  @media (max-width: 61.24em) {
    body:has(.article__references--visible) .site-header {
      z-index: 13;
    }
    body:has(.article__references--visible) .site-header:before,
    body:has(.article__references--visible) .site-header:after {
      content: "";
      display: block;
      position: fixed;
      z-index: 11;
      background: rgba(0, 0, 0, 0.38);
      top: 0;
      right: 0;
      bottom: 0;
      left: 0;
      position: absolute;
      z-index: 13;
    }
    body:has(.article__references--visible) .site-header:after {
      background: var(--color-header-background);
      z-index: 12;
    }
    body:has(.article__references--visible) .site-header .site-header__inner {
      position: relative;
      z-index: 13;
    }
  }
  body.nav-open .site-header__nav-toggle svg:first-child {
    display: none;
  }
  .site-header__nav ul > li:hover > ul {
    display: block;
    position: absolute;
    right: -20px;
    top: 100%;
    background: var(--color-header-background);
    border: 1px solid var(--color-band);
    width: 240px;
    padding: 10px 0;
  }
  body.page-template-template-about .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-newsletters .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.search.search-results .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.search.search-no-results .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-course-landing .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-course-general-content
    .site-header__nav
    ul
    > li:hover
    > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-course-longform-content
    .site-header__nav
    ul
    > li:hover
    > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-opportunities .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-reading-list .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  body.page-template-template-media .site-header__nav ul > li:hover > ul {
    background: var(--color-band);
    border: 1px solid var(--color-paper);
  }
  .site-header__nav ul > li:hover > ul > li > a {
    color: currentColor;
    padding: 5px 20px;
  }
  .site-header__nav ul > li:hover > ul > li > a:hover {
    text-decoration: underline;
  }
  .site-footer {
    font-family: IRANYekan, Tahoma, sans-serif;
    font-weight: 300;
    position: relative;
    display: grid;
    color: var(--color-paper);
    margin-top: 30px;
    overflow: hidden;
    flex-shrink: 0;
  }
  @media (max-width: 44.99em) {
    .site-footer {
      font-size: 0.6875rem;
      line-height: 1.4;
      letter-spacing: normal;
    }
  }
  @media (min-width: 45em) {
    .site-footer {
      font-size: 0.8125rem;
      line-height: 1.3;
      letter-spacing: normal;
    }
  }
  @media (max-width: 61.24em) {
    .site-footer {
      padding-right: 24px;
    }
  }
  @media (min-width: 61.25em) and (max-width: 63.99em) {
    .site-footer {
      padding-right: 36px;
    }
  }
  @media (min-width: 64em) {
    .site-footer {
      padding-right: 60px;
    }
  }
  @media (max-width: 61.24em) {
    .site-footer {
      padding-left: 24px;
    }
  }
  @media (min-width: 61.25em) and (max-width: 63.99em) {
