      padding-left: 36px;
    }
  }
  @media (min-width: 64em) {
    .site-footer {
      padding-left: 60px;
    }
  }
  .site-footer:before {
    content: "";
    display: block;
    width: 100vw;
    position: relative;
    right: 50%;
    left: 50%;
    margin-right: -50vw;
    margin-left: -50vw;
    background-color: var(--color-band);
    position: absolute;
    top: 0;
    bottom: 0;
    z-index: -1;
  }
  @media (min-width: 61.25em) {
    .site-footer {
      grid-template-columns: auto 1fr 177px;
      grid-template-areas: "logo    main-menu social" "address main-menu copyright" "address main-menu mini-menu";
      row-gap: 8px;
      column-gap: 40px;
      padding-top: 40px;
      padding-bottom: 40px;
    }
  }
  @media (max-width: 61.24em) {
    .site-footer {
      grid-template-columns: auto 1fr;
      grid-template-areas: "logo    social" "address copyright" "address mini-menu";
      row-gap: 10px;
      column-gap: 10px;
      padding-top: var(--default-spacing);
      padding-bottom: var(--default-spacing);
    }
  }
  .newsletter-pre-footer + .site-footer {
    margin-top: 0;
  }
  .site-footer a {
    text-underline-offset: 3px;
  }
  .site-footer__logo {
    grid-area: logo;
  }
  @media (max-width: 61.24em) {
    .site-footer__logo {
      width: 20px;
    }
  }
  @media (min-width: 61.25em) {
    .site-footer__logo {
      width: 38px;
    }
  }
  .site-footer__logo svg {
    width: 100%;
    height: auto;
  }
  .site-footer__address {
    grid-area: address;
    margin-top: auto;
  }
  @media (max-width: 61.24em) {
    .site-footer__address {
      align-self: end;
    }
  }
  .site-footer__main-menu {
    grid-area: main-menu;
  }
  @media (max-width: 61.24em) {
    .site-footer__main-menu {
      display: none;
    }
  }
  .site-footer__main-menu .menu {
    display: flex;
    justify-content: center;
    column-gap: 60px;
  }
  .site-footer__main-menu .menu a {
    display: block;
    text-decoration: none;
  }
  .site-footer__main-menu .menu > li > a {
    font-size: 0.6875rem;
    line-height: 1.3;
    font-weight: 900;
    text-transform: none;
    letter-spacing: normal;
    margin-bottom: 15px;
  }
  .site-footer__main-menu .menu > li > a[href="#"] {
    pointer-events: none;
  }
  .site-footer__main-menu .menu .sub-menu li a {
    font-family: IRANYekan, Tahoma, sans-serif;
    font-weight: 300;
    margin-bottom: 8px;
  }
  @media (max-width: 44.99em) {
    .site-footer__main-menu .menu .sub-menu li a {
      font-size: 0.6875rem;
      line-height: 1.4;
      letter-spacing: normal;
    }
  }
  @media (min-width: 45em) {
    .site-footer__main-menu .menu .sub-menu li a {
      font-size: 0.8125rem;
      line-height: 1.3;
      letter-spacing: normal;
