  @media (max-width: 61.24em) {
    .site-footer__copyright {
      text-align: left;
    }
  }
  .site-footer__copyright a {
    text-decoration: none;
  }
  .site-footer__mini-menu {
    grid-area: mini-menu;
  }
  .site-footer__mini-menu ul {
    display: flex;
    flex-direction: column;
    row-gap: 8px;
  }
  @media (max-width: 61.24em) {
    .site-footer__mini-menu ul {
      align-items: flex-end;
    }
